    auto eqFirst=source;auto& fx=eqFirst.masterMixer;fx.eq=fx.compressor=true;fx.low=12;fx.high=8;fx.threshold=-32;fx.ratio=8;fx.compAttack=.1f;auto a=render(eqFirst,assets,root,96000,127);fx.order={1,0,2,3,4,5};auto b=render(eqFirst,assets,root,96000,127);double difference=0;for(int c=0;c<2;++c)for(int i=0;i<96000;++i)difference+=std::abs(a.getSample(c,i)-b.getSample(c,i));expect(difference>1,"reordering Master EQ and compression changes the nonlinear processing order");
    auto perSource=source;for(int t:{5,7})perSource.tracks[(size_t)t].mixer=eqFirst.masterMixer;perSource.masterMixer={};auto independent=render(perSource,assets,root,96000,127);difference=0;for(int c=0;c<2;++c)for(int i=0;i<96000;++i)difference+=std::abs(b.getSample(c,i)-independent.getSample(c,i));expect(difference>1,"Master dynamics operate once on the sum rather than independently per source");
    auto callback=render(full,assets,root,144000,127);RenderSettings encoding;encoding.bits=32;encoding.endBeat=4;encoding.tailSeconds=1;auto wave=root.getChildFile("master-inserts-export.wav");expect(renderAudio(full,assets,root,wave,encoding).wasOk(),"Master inserts render through the native offline exporter");String error;auto* exported=assets.load(wave,error);bool equal=exported&&exported->audio.getNumSamples()==144000;if(equal)for(int c=0;c<2;++c)for(int i=0;i<144000;++i)equal&=std::abs(callback.getSample(c,i)-exported->audio.getSample(c,i))<.000001f;expect(equal,"float export matches live Master processing sample for sample");
    auto preview=makeEngine(full,assets,root);preview->stop();Sample raw;raw.audio.setSize(2,2048);for(int i=0;i<2048;++i){raw.audio.setSample(0,i,.25f);raw.audio.setSample(1,i,-.125f);}preview->preview(&raw);AudioBuffer<float> output(2,512);preview->render(output.getWritePointer(0),output.getWritePointer(1),512);bool dry=true;for(int i=0;i<512;++i)dry&=output.getSample(0,i)==.175f&&output.getSample(1,i)==-.0875f;expect(dry,"explicit Browser preview stays at original-speed dry gain outside Master inserts");
    auto compiled=std::make_unique<Playback>();String warnings;auto corrupt=full;corrupt.masterMixer.output=0;expect(compilePlayback(corrupt,assets,root,*compiled,warnings).failed(),"Master cannot be routed back into the channel graph");corrupt=full;corrupt.masterMixer.sidechain=0;expect(compilePlayback(corrupt,assets,root,*compiled,warnings).failed(),"Master compressor rejects unavailable external detector routes");corrupt=full;corrupt.masterMixer.low=std::numeric_limits<float>::quiet_NaN();expect(compilePlayback(corrupt,assets,root,*compiled,warnings).failed(),"nonfinite Master settings never reach the callback");auto saved=file.loadFileAsString();expect(saveProject(corrupt,file).failed()&&file.loadFileAsString()==saved,"invalid Master data cannot overwrite a valid saved project");
    for(int bad=0;bad<7;++bad){auto invalid=projectToJson(full);auto* rootObject=invalid.getDynamicObject();if(bad==0)rootObject->removeProperty("masterEffects");else{auto* master=invalid["masterEffects"].getDynamicObject();if(bad==1)master->removeProperty("stereo");if(bad==2)master->setProperty("output",0);if(bad==3)master->setProperty("sidechain",false);if(bad==4)master->setProperty("chain","bad");if(bad==5)invalid["masterEffects"]["chain"]["settings"].getDynamicObject()->setProperty("compressor",1);if(bad==6)invalid["masterEffects"]["chain"]["settings"].getDynamicObject()->setProperty("ratio",21);}auto before=JSON::toString(projectToJson(loaded));expect(projectFromJson(invalid,loaded).failed()&&JSON::toString(projectToJson(loaded))==before,"incomplete or invalid Master project settings reject without changing the destination");}
    Project edited;auto edit=JSON::parse(R"([{"op":"set_song","masterEffects":{"order":[4,0,1,3,5,2],"compressor":{"threshold":-24,"ratio":3,"attack":5,"release":160,"makeup":1},"flanger":{"mix":0.15,"rate":0.2,"centre":3},"phaser":{"enabled":false,"centre":1200},"stereo":{"mono":true}}},{"op":"set_track","track":5,"effects":{"compressor":{"ratio":4},"order":[1,0,2,3,4,5]}}])");expect(applyControlEdits(source,edit,edited).wasOk()&&edited.masterMixer.compressor&&edited.masterMixer.flanger.enabled&&!edited.masterMixer.phaser.enabled&&edited.masterMixer.stereo.mono&&edited.masterMixer.order==m.order&&edited.tracks[5].mixer.compressor&&edited.tracks[5].mixer.order[0]==1,"atomic MCP edits expose complete Master and channel insert processing");
    for(const char* bad:{R"([{"op":"set_song","masterEffects":{"output":0}}])",R"([{"op":"set_song","masterEffects":{"compressor":{"sidechain":0}}}])",R"([{"op":"set_song","masterEffects":{"order":[0,0,2,3,4,5]}}])",R"([{"op":"set_song","masterEffects":{"chorus":{"enabled":1}}}])",R"([{"op":"set_song","masterEffects":{"phaser":{"centre":4001}}}])",R"([{"op":"set_song","masterEffects":{"compressor":{"threshold":-61}}}])",R"([{"op":"set_song","masterEffects":{"eq":{"low":3}}},{"op":"set_track","track":5,"effects":{"flanger":{"rate":6}}}])"}){auto candidate=edited;auto before=JSON::toString(projectToJson(candidate));expect(applyControlEdits(source,JSON::parse(bad),candidate).failed()&&JSON::toString(projectToJson(candidate))==before,"invalid Master/channel effect edit rejects the entire MCP batch atomically");}
